### Complete Workflow Reference

The following is the canonical reference workflow. Copy this into `.github/workflows/agent-dispatch.yml` and customize the sections marked with `# CONFIGURE:`.

```yaml
# .github/workflows/agent-dispatch.yml
# AI Agent Dispatch Pipeline — GUID-TECH-IMPL-002
# Implements PTN-TEC-AI-002 and is governed by STD-GOV-AI-001/002/003

name: AI Agent Dispatch

on:
  issues:
    types: [labeled]

# Minimum permissions — expanded per job only as needed
permissions:
  contents: read

jobs:
  # ─────────────────────────────────────────────────────────────────────────────
  # STAGE 1: VALIDATE
  # Parse spec, validate structure, run security screens.
  # Fail-closed: any failure removes agent-task and halts.
  # ─────────────────────────────────────────────────────────────────────────────
  validate-spec:
    name: Validate Agent Spec
    if: github.event.label.name == 'agent-task'
    runs-on: ubuntu-latest
    permissions:
      issues: write        # post comments, manage labels
    outputs:
      goal: ${{ steps.parse.outputs.goal }}
      acceptance_criteria: ${{ steps.parse.outputs.acceptance_criteria }}
      constraints: ${{ steps.parse.outputs.constraints }}
      enterprise_xref: ${{ steps.parse.outputs.enterprise_xref }}
      routing_label: ${{ steps.routing.outputs.routing_label }}
      agent_type: ${{ steps.routing.outputs.agent_type }}

    steps:
      - name: Enforce separation of duties — label actor ≠ issue author
        # ADR-GOV-010: The agent-task label must be applied by a second party,
        # not the spec author. This is the technical control implementing NIST 800-53 AC-5.
        id: sod-check
        uses: actions/github-script@v7
        with:
          script: |
            const labelActor = context.payload.sender.login;
            const issueAuthor = context.payload.issue.user.login;
            if (labelActor === issueAuthor) {
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.payload.issue.number,
                body: '⛔ **Agent dispatch blocked.** The `agent-task` label must be applied by someone other than the issue author. This is a separation-of-duties control ([ADR-GOV-010](../../../../decisions/governance/ADR-GOV-010-ai-agent-label-trigger-control-model.md)). Ask a peer reviewer or team lead to review your spec and apply the label.',
              });
              core.setFailed('SOD_VIOLATION: label actor equals issue author');
            }

      - name: Parse spec sections
        id: parse
        uses: actions/github-script@v7
        with:
          script: |
            const body = context.payload.issue.body ?? '';

            // Extract structured sections only — do not pass raw body downstream
            function extractSection(body, header) {
              const pattern = new RegExp(
                `## ${header}\\s*\\n([\\s\\S]*?)(?=\\n## |$)`, 'i'
              );
              const match = body.match(pattern);
              return match ? match[1].trim() : '';
            }

            const goal = extractSection(body, 'Goal');
            const criteria = extractSection(body, 'Acceptance Criteria');
            const constraints = extractSection(body, 'Constraints');
            const workItem = extractSection(body, 'Enterprise Work Item');

            // Validate all sections are present
            const missing = [];
            if (!goal) missing.push('Goal');
            if (!criteria) missing.push('Acceptance Criteria');
            if (!constraints) missing.push('Constraints');
            if (!workItem) missing.push('Enterprise Work Item');

            if (missing.length > 0) {
              core.setFailed(`Spec is missing required sections: ${missing.join(', ')}`);
              core.exportVariable('FAIL_REASON', `Missing sections: ${missing.join(', ')}`);
              return;
            }

            // Validate acceptance criteria: minimum 2 checkable items
            const checkboxes = (criteria.match(/^[-*] \[[ x]\]/gm) ?? []);
            if (checkboxes.length < 2) {
              core.setFailed('Acceptance Criteria must contain at least 2 checkbox items (- [ ] or - [x])');
              core.exportVariable('FAIL_REASON', 'Fewer than 2 acceptance criteria checkboxes found');
              return;
            }

            // Validate enterprise work item cross-reference format
            // CONFIGURE: Update pattern to match your enterprise platform format
            // Azure DevOps:  /WI#\d+/
            // GitHub/ADO:    /AB#\d+/
            const xrefPattern = /WI#\d+|AB#\d+/;
            const xrefMatch = workItem.match(xrefPattern);
            if (!xrefMatch) {
              core.setFailed('Enterprise Work Item section does not contain a valid cross-reference (e.g., WI#1234 or AB#1234)');
              core.exportVariable('FAIL_REASON', 'Invalid or missing enterprise work item cross-reference');
              return;
            }

            core.setOutput('goal', goal);
            core.setOutput('acceptance_criteria', criteria);
            core.setOutput('constraints', constraints);
            core.setOutput('enterprise_xref', xrefMatch[0]);

      - name: Screen for injection and PHI patterns
        id: screen
        uses: actions/github-script@v7
        with:
          script: |
            const body = context.payload.issue.body ?? '';

            // Prompt injection patterns — case insensitive
            const injectionPatterns = [
              /ignore (previous|all|above|prior) instructions/i,
              /system\s*prompt/i,
              /you are now/i,
              /disregard your/i,
              /forget everything/i,
              /new persona/i,
              /developer mode/i,
              /jailbreak/i,
              /base64\s*decode/i,
              /eval\s*\(/i,
            ];

            // PHI indicator patterns — log pattern type only, never the matched value
            const phiPatterns = [
              { name: 'SSN-pattern', re: /\b\d{3}-\d{2}-\d{4}\b/ },
              { name: 'DOB-field',   re: /\bDOB\s*[:=]\s*\d/i },
              { name: 'MRN-field',   re: /\bMRN\s*#?\s*\d/i },
              { name: 'MemberID',    re: /\bMember\s*ID\s*[:=]\s*[A-Z0-9]/i },
              { name: 'NPI',         re: /\bNPI\s*[:=]\s*\d{10}/i },
              { name: 'ICD10-ref',   re: /\bICD-?10/i },
            ];

            const injectionHits = injectionPatterns.filter(p => p.test(body));
            const phiHits = phiPatterns.filter(p => p.re.test(body)).map(p => p.name);

            if (injectionHits.length > 0) {
              // Do not echo matched content — log detection event only
              core.error('Security: Potential prompt injection pattern detected in issue body. Pipeline halted.');
              core.setFailed('SECURITY_INJECTION_DETECTED');
              core.exportVariable('FAIL_REASON', 'Prompt injection pattern detected');
              return;
            }

            if (phiHits.length > 0) {
              core.error(`Security: Potential PHI indicator(s) detected: ${phiHits.join(', ')}. Issue body must not contain protected health information.`);
              core.setFailed('SECURITY_PHI_DETECTED');
              core.exportVariable('FAIL_REASON', `PHI patterns detected: ${phiHits.join(', ')}`);
              return;
            }

      - name: Validate routing label
        id: routing
        uses: actions/github-script@v7
        with:
          script: |
            const labels = context.payload.issue.labels.map(l => l.name);
            const routingLabels = [
              'agent:implementation',
              'agent:documentation',
              'agent:testing',
              'agent:infrastructure',
            ];
            // CONFIGURE: Add new routing labels here after EA Practice approval (STD-GOV-AI-002)
            const agentTypeMap = {
              'agent:implementation': 'implementation',
              'agent:documentation':  'documentation',
              'agent:testing':        'testing',
              'agent:infrastructure': 'infrastructure',
            };

            const presentRouting = labels.filter(l => routingLabels.includes(l));

            if (presentRouting.length === 0) {
              core.setFailed('No routing label found. Apply exactly one of: ' + routingLabels.join(', '));
              core.exportVariable('FAIL_REASON', 'Missing routing label');
              return;
            }
            if (presentRouting.length > 1) {
              core.setFailed('Multiple routing labels found: ' + presentRouting.join(', ') + '. Apply exactly one.');
              core.exportVariable('FAIL_REASON', 'Multiple routing labels: ' + presentRouting.join(', '));
              return;
            }

            core.setOutput('routing_label', presentRouting[0]);
            core.setOutput('agent_type', agentTypeMap[presentRouting[0]]);

      - name: Post corrective comment and clean up on failure
        if: failure()
        uses: actions/github-script@v7
        with:
          script: |
            const reason = process.env.FAIL_REASON ?? 'Validation error (check pipeline logs for details)';
            const isSecurity = reason.startsWith('SECURITY_') || reason.includes('injection') || reason.includes('PHI');

            let body;
            if (isSecurity) {
              body = `## ⛔ Agent Dispatch Blocked — Security Screen Failed\n\n` +
                `A security screen detected a potential issue with this spec. ` +
                `The pipeline has been halted and the \`agent-task\` label has been removed.\n\n` +
                `Please review the issue body for content that should not be present in an agent task spec, ` +
                `then contact your security team if you believe this is a false positive.\n\n` +
                `> Detected: ${reason}\n\n` +
                `Re-apply \`agent-task\` after the issue is resolved.`;
            } else {
              body = `## ⚠️ Agent Dispatch Incomplete — Spec Validation Failed\n\n` +
                `The \`agent-task\` label was applied but the spec did not pass validation.\n\n` +
                `**Reason:** ${reason}\n\n` +
                `Please correct the spec and re-apply \`agent-task\` when ready. ` +
                `See [STD-GOV-AI-001](../../standards/governance/ai-development/STD-GOV-AI-001-agent-executable-work-item-specification-standard.md) for requirements.`;
            }

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body,
            });

            // Remove agent-task to prevent re-trigger loops
            await github.rest.issues.removeLabel({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              name: 'agent-task',
            }).catch(() => {});  // Ignore if already removed

  # ─────────────────────────────────────────────────────────────────────────────
  # STAGE 2: DISPATCH
  # Assemble context, invoke agent, commit output to feature branch.
  # Fail-closed: any failure applies agent:blocked and halts.
  # ─────────────────────────────────────────────────────────────────────────────
  dispatch-agent:
    name: Dispatch Agent
    needs: validate-spec
    runs-on: ubuntu-latest
    permissions:
      contents: write      # write to agent/* branches only
      issues: write        # post comments, apply labels
    outputs:
      branch_name: ${{ steps.branch.outputs.branch_name }}
      model_id: ${{ steps.invoke.outputs.model_id }}

    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          token: ${{ secrets.AGENT_SERVICE_TOKEN }}
          # CONFIGURE: AGENT_SERVICE_TOKEN is the service account PAT or app token.
          # Scope: contents:write (agent/* branches), pull-requests:write, issues:write.
          # It MUST NOT have merge or admin permissions. See STD-GOV-AI-003 REQ-006.

      - name: Create agent branch
        id: branch
        run: |
          ISSUE_NUMBER="${{ github.event.issue.number }}"
          GOAL="${{ needs.validate-spec.outputs.goal }}"
          # Slugify: lowercase, spaces to hyphens, strip non-alphanumeric (except hyphens), max 40 chars
          GOAL_SLUG=$(echo "$GOAL" | tr '[:upper:]' '[:lower:]' | tr ' ' '-' | tr -cd '[:alnum:]-' | cut -c1-40)
          BRANCH_NAME="agent/${ISSUE_NUMBER}-${GOAL_SLUG}"
          echo "branch_name=${BRANCH_NAME}" >> "$GITHUB_OUTPUT"
          git config user.name "agent-bot[bot]"
          # CONFIGURE: Replace with your service account's email
          git config user.email "agent-bot@users.noreply.github.com"
          git checkout -b "${BRANCH_NAME}"

      - name: Assemble agent context
        id: context
        env:
          SPEC_GOAL: ${{ needs.validate-spec.outputs.goal }}
          SPEC_ACCEPTANCE_CRITERIA: ${{ needs.validate-spec.outputs.acceptance_criteria }}
          SPEC_CONSTRAINTS: ${{ needs.validate-spec.outputs.constraints }}
          SPEC_ENTERPRISE_XREF: ${{ needs.validate-spec.outputs.enterprise_xref }}
          SPEC_ISSUE_NUMBER: ${{ github.event.issue.number }}
          SPEC_REPOSITORY: ${{ github.repository }}
          SPEC_BRANCH: ${{ steps.branch.outputs.branch_name }}
        run: |
          # CONFIGURE: Update context_files to match your agent routing config.
          # Load routing configuration from version-controlled file.
          AGENT_TYPE="${{ needs.validate-spec.outputs.agent_type }}"
          CONFIG_FILE="configs/agents/${AGENT_TYPE}-agent.yaml"
          if [[ ! -f "$CONFIG_FILE" ]]; then
            echo "ERROR: Agent config not found: ${CONFIG_FILE}" >&2
            exit 1
          fi

          # Assemble structured context safely via environment variables and jq.
          # This avoids shell interpolation of spec text containing quotes or metacharacters.
          jq -n \
            --arg goal "$SPEC_GOAL" \
            --arg acceptance_criteria "$SPEC_ACCEPTANCE_CRITERIA" \
            --arg constraints "$SPEC_CONSTRAINTS" \
            --arg enterprise_xref "$SPEC_ENTERPRISE_XREF" \
            --argjson issue_number "$SPEC_ISSUE_NUMBER" \
            --arg repository "$SPEC_REPOSITORY" \
            --arg branch "$SPEC_BRANCH" \
            '{
              goal: $goal,
              acceptance_criteria: $acceptance_criteria,
              constraints: $constraints,
              enterprise_xref: $enterprise_xref,
              issue_number: $issue_number,
              repository: $repository,
              branch: $branch
            }' > /tmp/agent-context.json

      - name: Invoke agent
        id: invoke
        timeout-minutes: 10
        # CONFIGURE: Replace this step with your organization's agent invocation mechanism.
        # Options:
        #   A) GitHub Copilot Coding Agent — use the gh-copilot-agent action (see Examples section)
        #   B) Custom agent CLI — call your agent CLI binary with the context JSON
        #   C) API-based agent — POST to your agent orchestration API with the context
        #
        # The agent MUST:
        #   - Read /tmp/agent-context.json as its task specification
        #   - Write all output files to the working directory (which is on the agent branch)
        #   - Exit 0 on success, non-zero on failure
        #   - Write its model identifier to /tmp/agent-model-id (single line, e.g. "copilot-gpt-4o")
        #
        # Example for a CLI-based agent:
        run: |
          # REPLACE THIS BLOCK with your agent invocation
          echo "ERROR: Agent invocation is not configured. See GUID-TECH-IMPL-002 implementation guidance." >&2
          echo "Configure the 'invoke agent' step in .github/workflows/agent-dispatch.yml" >&2
          exit 1

          # When configured, the step should populate model_id:
          # MODEL_ID=$(cat /tmp/agent-model-id 2>/dev/null || echo "unknown")
          # echo "model_id=${MODEL_ID}" >> "$GITHUB_OUTPUT"
        env:
          AGENT_API_KEY: ${{ secrets.AGENT_API_KEY }}
          # CONFIGURE: Add agent API credentials as repository secrets, not hardcoded values.
          # Use OIDC token exchange if your agent platform supports it (preferred over static keys).

      - name: Validate agent produced output
        id: validate-output
        run: |
          # Check that the agent actually modified at least one file
          CHANGED=$(git status --porcelain | wc -l)
          if [[ "$CHANGED" -eq 0 ]]; then
            echo "ERROR: Agent completed but produced no file changes." >&2
            echo "Review the agent log and spec — the Goal may be too abstract for the agent to act on." >&2
            exit 1
          fi
          echo "Agent produced ${CHANGED} changed file(s)."

      - name: Commit agent output
        run: |
          git add -A
          git commit -m "agent: ${{ needs.validate-spec.outputs.goal }} (#${{ github.event.issue.number }})"
          git push origin "${{ steps.branch.outputs.branch_name }}"

      - name: Apply blocked label and post failure comment on dispatch failure
        if: failure()
        uses: actions/github-script@v7
        with:
          script: |
            await github.rest.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              labels: ['agent:blocked'],
            });

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body: `## 🔴 Agent Dispatch Failed\n\n` +
                `The agent dispatch pipeline failed during execution. ` +
                `The \`agent:blocked\` label has been applied.\n\n` +
                `**Pipeline run:** ${{ github.server_url }}/${{ github.repository }}/actions/runs/${{ github.run_id }}\n\n` +
                `Review the pipeline log for the failure details. ` +
                `Remove \`agent:blocked\`, resolve the issue, and re-apply \`agent-task\` to retry.`,
            });

  # ─────────────────────────────────────────────────────────────────────────────
  # STAGE 3: REPORT
  # Create PR with mandatory traceability block. Apply agent:complete.
  # Fail-closed: PR creation failure applies agent:blocked.
  # ─────────────────────────────────────────────────────────────────────────────
  create-pr:
    name: Create PR with Traceability
    needs: [validate-spec, dispatch-agent]
    runs-on: ubuntu-latest
    permissions:
      contents: read
      pull-requests: write
      issues: write

    steps:
      - name: Assemble PR body with traceability block
        id: pr-body
        uses: actions/github-script@v7
        with:
          result-encoding: string
          script: |
            const goal = `${{ needs.validate-spec.outputs.goal }}`;
            const criteria = `${{ needs.validate-spec.outputs.acceptance_criteria }}`;
            const xref = `${{ needs.validate-spec.outputs.enterprise_xref }}`;
            const issueNum = context.issue.number;
            const agentType = `${{ needs.validate-spec.outputs.agent_type }}`;
            const modelId = `${{ needs.dispatch-agent.outputs.model_id }}`;
            const runId = context.runId;
            const runUrl = `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${runId}`;
            const timestamp = new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');

            return [
              `## Summary`,
              ``,
              `> Agent-executed task. Goal: ${goal}`,
              ``,
              `## Acceptance Criteria`,
              ``,
              criteria,
              ``,
              `---`,
              ``,
              `## Traceability`,
              ``,
              `| Field | Value |`,
              `|---|---|`,
              `| **Enterprise Work Item** | ${xref} |`,
              `| **Agent Task Issue** | #${issueNum} |`,
              `| **Agent Type** | ${agentType} |`,
              `| **Pipeline Run** | [${runId}](${runUrl}) |`,
              `| **Generated** | ${timestamp} |`,
              `| **Model** | ${modelId} |`,
            ].join('\n');

      - name: Create pull request
        id: create-pr
        uses: actions/github-script@v7
        with:
          script: |
            const branchName = `${{ needs.dispatch-agent.outputs.branch_name }}`;
            const goal = `${{ needs.validate-spec.outputs.goal }}`;
            const issueNum = context.issue.number;

            const pr = await github.rest.pulls.create({
              owner: context.repo.owner,
              repo: context.repo.repo,
              title: `[AGENT] ${goal} (#${issueNum})`,
              head: branchName,
              base: 'main',
              // CONFIGURE: Update 'main' to match your default branch name
              body: `${{ steps.pr-body.outputs.result }}`,
              draft: false,
            });

            core.setOutput('pr_number', pr.data.number);
            core.setOutput('pr_url', pr.data.html_url);

      - name: Apply agent:complete and post success comment
        uses: actions/github-script@v7
        with:
          script: |
            const prUrl = `${{ steps.create-pr.outputs.pr_url }}`;
            const prNumber = `${{ steps.create-pr.outputs.pr_number }}`;

            // Remove agent-task (prevent re-trigger if re-opened)
            await github.rest.issues.removeLabel({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              name: 'agent-task',
            }).catch(() => {});

            // Apply agent:complete — pipeline-managed status label
            await github.rest.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              labels: ['agent:complete'],
            });

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body: `## ✅ Agent Task Complete\n\n` +
                `The agent has completed execution and created a pull request for human review.\n\n` +
                `**PR:** ${prUrl}\n\n` +
                `A human reviewer must approve and merge the PR. ` +
                `See [GUID-GOV-IMPL-004](../../strategy/guidance/governance/implementation/GUID-GOV-IMPL-004-ai-agent-pr-review-guidance.md) for review guidance.`,
            });

      - name: Apply blocked label on PR creation failure
        if: failure()
        uses: actions/github-script@v7
        with:
          script: |
            await github.rest.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              labels: ['agent:blocked'],
            });
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body: `## 🔴 PR Creation Failed\n\n` +
                `The agent completed execution but the pull request creation step failed. ` +
                `The agent branch exists but no PR was opened.\n\n` +
                `**Pipeline run:** ${{ github.server_url }}/${{ github.repository }}/actions/runs/${{ github.run_id }}\n\n` +
                `Review the pipeline log. You may be able to manually open the PR from the agent branch.`,
            });
```

